import{_ as e,c as a,a2 as p,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第六章 富有后能够管束好自己的人很少","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/6第六章 富有后能够管束好自己的人很少.md","filePath":"meditation/巴利文大藏经/6第六章 富有后能够管束好自己的人很少.md"}'),o={name:"meditation/巴利文大藏经/6第六章 富有后能够管束好自己的人很少.md"};function r(n,t,i,s,d,c){return _(),a("div",null,t[0]||(t[0]=[p('<h1 id="第六章-富有后能够管束好自己的人很少" tabindex="-1">第六章 富有后能够管束好自己的人很少 <a class="header-anchor" href="#第六章-富有后能够管束好自己的人很少" aria-label="Permalink to &quot;第六章 富有后能够管束好自己的人很少&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部3相应6经/少经(憍萨罗相应/有偈篇/祇夜)</p><p>有个时候，骄萨罗国的波斯匿王来到佛陀的住所，顶礼佛陀后，波斯匿王在一旁坐下，他对佛陀说：“世尊，我独自静坐的时候，内心生起这样的念想：在世间获得大量财富、富甲天下的人，他们在获得巨额财富后，不沉迷享受，不放任自己胡作非为，不贪求对欲望的满足，不侵害别人的人是非常少的。相反的这些家财万贯的人，当他们获得巨额财富后，在各种欲乐中醉生梦死、放纵任性、作威作福、为所欲为，对各种欲望的贪求无有止境，损害、伤害别人的人，这样的人是非常的多的。”</p><p>佛陀说：“大王，正如你所说，确实是这样的。</p><p>大王，世间那些在获得大量财富后，不沉迷享受，不放任自己胡作非为，不贪求对欲望的满足，不侵害别人的人是极少数的人，更多获得巨额财富的人，他们沉迷于各种欲乐的享受，横行无忌、随心所欲、任性妄为，毫不管束自己的行为，侵害、伤害别人。</p><p>大王，这些人因为获得巨额财富的缘故，他们沉迷于各种欲望的享受，被各种欲望束缚、捆绑。他们已经成为贪欲的奴隶，贪欲已经控制住了他们的心，他们已经不知不觉的跨越了不该跨越的界限，就如同麋鹿进入了诡诈的陷阱，被猎人抓住。这些获得巨额财富、任性妄为、贪无止境的人，他们最终的结局是非常痛苦和悲惨的，因为他们肆无忌惮、横行无忌的行为将会为他们自己造下无数的罪业，而当他们的福报耗尽后，就将去承受这些罪业结出来的痛苦果报，当初他们为所欲为给别人带来了多大的痛苦，他们自己就将去承受同样大小的痛苦。当然他们过惯锦衣玉食的生活后，再去过穷困潦倒的生活也是非常痛苦的。”</p><p>这时，佛陀说偈言：</p><p>「富迷于欲乐，贪欲以夺心。</p><p>不觉于道外，如鹿被缚蹄。</p><p>彼等后苦涩，其果即是恶。」</p>',11)]))}const f=e(o,[["render",r]]);export{m as __pageData,f as default};
